import java.util.*;

class Solution {
    public int countNodes(TreeNode root) {
        if (root == null) return 0;
        int l = 0, r = 0;
        for (TreeNode a = root; a != null; a = a.left) l++;   // leftmost depth
        for (TreeNode b = root; b != null; b = b.right) r++;  // rightmost depth
        if (l == r) return (1 << l) - 1;                      // perfect subtree
        return 1 + countNodes(root.left) + countNodes(root.right);
    }
}

