class Solution:
    def countNodes(self, root: Optional[TreeNode]) -> int:
        if not root: return 0
        l, r, a, b = 0, 0, root, root
        while a: l += 1; a = a.left
        while b: r += 1; b = b.right
        if l == r: return (1 << l) - 1
        return 1 + self.countNodes(root.left) + self.countNodes(root.right)

